def frame(mark):
    g = [[0]*15 for _ in range(15)]
    for c in range(3,12):
        g[2][c] = g[10][c] = 3
    for r in range(2,11):
        g[r][3] = g[r][11] = 3
    g[3+mark[0]][4+mark[1]] = 3
    return g

def expected(mark, twos):
    g = frame(mark)
    for r in range(3,10):
        for c in range(4,11): g[r][c] = 4
    for rr,cc in twos: g[3+rr][4+cc] = 2
    g[3+mark[0]][4+mark[1]] = 3
    return g
